import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CMpzMyBe.js";const m=JSON.parse('{"title":"ADR 003 - Zero-copy DogStatsD framing over pooled I/O buffers","description":"","frontmatter":{"date":"2026-11-06T00:00:00.000Z","title":"ADR 003 - Zero-copy DogStatsD framing over pooled I/O buffers"},"headers":[],"relativePath":"reference/adrs/records/003-zero-copy-dogstatsd-framing.md","filePath":"reference/adrs/records/003-zero-copy-dogstatsd-framing.md","lastUpdated":1794576209000}'),s={name:"reference/adrs/records/003-zero-copy-dogstatsd-framing.md"};function n(d,e,i,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-003-zero-copy-dogstatsd-framing-over-pooled-i-o-buffers" tabindex="-1">ADR 003 - Zero-copy DogStatsD framing over pooled I/O buffers <a class="header-anchor" href="#adr-003-zero-copy-dogstatsd-framing-over-pooled-i-o-buffers" aria-label="Permalink to &quot;ADR 003 - Zero-copy DogStatsD framing over pooled I/O buffers&quot;">​</a></h1><h2 id="problem-statement" tabindex="-1">Problem statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem statement&quot;">​</a></h2><p>The DogStatsD source allocates memory for every packet it receives. Each frame is copied out of the pooled I/O buffer before the codec reads it, even though the codec only needs to borrow the bytes. Allocation is also expensive in Agent Data Plane (ADP): it runs jemalloc without a thread cache, so every allocation and free goes to the shared arena.</p><p>How do we hand frames to the codec without copying them, while keeping pooled I/O buffers and the way we read into them?</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><h3 id="how-framing-works-today" tabindex="-1">How framing works today <a class="header-anchor" href="#how-framing-works-today" aria-label="Permalink to &quot;How framing works today&quot;">​</a></h3><p>DogStatsD reads from the socket into a <code>BytesBuffer</code> from a bounded object pool, then cuts frames off the front of that buffer until no complete frame remains. Connected streams collapse the leftover bytes and read again. There are two framings:</p><ul><li><strong>Direct:</strong> newline-delimited messages, for UDP, Unix datagram sockets, and named pipes.</li><li><strong>Nested:</strong> length-delimited outer frames holding newline-delimited messages, for Unix stream sockets and TCP.</li></ul><p>Framers return frames as <code>Bytes</code>, using <code>Buf::copy_to_bytes</code>. On <code>BytesBuffer</code> that&#39;s the default implementation: allocate and copy. <code>NestedFramer</code> holds each outer frame as <code>Bytes</code>, and splitting a message out of a <code>Bytes</code> that came from a <code>Vec</code> allocates a shared header on the first split. Allocations per message:</p><table tabindex="0"><thead><tr><th>Listener</th><th>Allocations</th></tr></thead><tbody><tr><td>UDP, Unix datagram, named pipe</td><td>1 per message</td></tr><tr><td>Unix stream or TCP, one message per outer frame</td><td>2 per message</td></tr><tr><td>Unix stream or TCP, many messages per outer frame</td><td>2 per outer frame</td></tr></tbody></table><p>Under ADP&#39;s jemalloc configuration, this framing is 33% to 49% of the combined time to frame and parse a message.</p><h3 id="why-not-bytes-and-bytesmut" tabindex="-1">Why not <code>Bytes</code> and <code>BytesMut</code> <a class="header-anchor" href="#why-not-bytes-and-bytesmut" aria-label="Permalink to &quot;Why not `Bytes` and `BytesMut`&quot;">​</a></h3><p>The <a href="https://docs.rs/bytes" target="_blank" rel="noreferrer"><code>bytes</code></a> crate makes slicing cheap by reference counting, but a frozen <code>Bytes</code> can only be turned back into a <code>BytesMut</code> fallibly, so <code>bytes</code> can&#39;t guarantee that at most N I/O buffers exist. We need that guarantee for deterministic memory use, which is why <code>BytesBuffer</code> and its pool exist, and why <code>copy_to_bytes</code> on it degrades to a copy.</p><h3 id="a-previous-attempt" tabindex="-1">A previous attempt <a class="header-anchor" href="#a-previous-attempt" aria-label="Permalink to &quot;A previous attempt&quot;">​</a></h3><p><a href="https://github.com/DataDog/saluki/pull/983" target="_blank" rel="noreferrer">#983</a> switched framers to borrowed slices. To hand out slices of the buffer while still advancing it afterwards, its <code>Framed</code> type converted <code>&amp;mut</code> to a raw pointer and advanced the buffer when dropped. That was sound, but fragile: the safety argument lived in comments, nested framing was a hard-coded mode rather than a framer, every frame went through dynamic dispatch, and framers lost access to the buffer&#39;s capacity.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li>No allocation or copy per frame when the consumer only borrows it.</li><li>Keep the pooled <code>BytesBuffer</code>, and the read, frame, collapse, read cycle.</li><li>A frame must never be handed out without the buffer having been advanced past it by exactly the right amount. This should hold by construction, not because a drop guard or deferred step runs.</li><li>Frames come off the front of the buffer only. Partial frames stay in the buffer for the next read.</li><li>Nested framing must perform as well as direct framing.</li><li>Today&#39;s EOF, error, and size-limit behavior is unchanged, as are the hooks the source uses: completed outer frame counts and outer frame capture.</li><li>A frame can be held across <code>.await</code> in the decode loop.</li><li>No <code>unsafe</code> code.</li></ul><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><p>Each option was built as a prototype and measured in a shared benchmark harness with DogStatsD workloads modeled on the SMP regression cases. Before any timing, each prototype had to pass a conformance suite that compared it against today&#39;s framing, using direct and nested layouts, randomized read sizes, and edge cases.</p><ul><li><strong>PR #983&#39;s design</strong>: framers over <code>&amp;mut &amp;[u8]</code>, with the buffer advanced on drop through a raw pointer.</li><li><strong>Span framers with deferred advancement</strong>: framers describe a frame&#39;s position without touching the buffer, and a lending iterator advances past each frame when the next one is requested, or on drop.</li><li><strong>Today&#39;s framer shape with a consume primitive</strong>: framers advance the buffer through a primitive that returns the bytes it advanced past.</li><li><strong>Span framers driven by the consume primitive</strong>: the two previous options combined, so advancement happens at once.</li><li><strong>Internal iteration</strong>: frames are passed to a closure, and the buffer is advanced once afterwards.</li><li><strong>Reference-counted slices</strong>: the pooled buffer is frozen behind <code>Bytes::from_owner</code>, and frames are <code>Bytes</code> slices of it. Leftover bytes are copied to a new buffer.</li><li><strong>A single DogStatsD framer over a split-borrow read cursor</strong>: the buffer lends a shared borrow of its bytes and an exclusive borrow of its read index. Taking a frame moves the read index, and in stream mode each outer frame is taken whole.</li></ul><h2 id="decision-outcome" tabindex="-1">Decision outcome <a class="header-anchor" href="#decision-outcome" aria-label="Permalink to &quot;Decision outcome&quot;">​</a></h2><p>Chosen option: <strong>A single DogStatsD framer over a split-borrow read cursor</strong></p><p>The buffer&#39;s bytes and its read index are separate fields, so the buffer can lend both at once: a shared borrow of the bytes, and an exclusive borrow of the read index. The cursor&#39;s <code>take(n)</code> moves the read index past <code>n</code> bytes, then returns them, borrowed for as long as the buffer is borrowed. That is the only way to get bytes that outlive the cursor, so every frame comes from bytes the buffer has already been advanced past, with no raw pointers and no drop step. The compiler stops the buffer from being collapsed, cleared, or written while any frame is alive.</p><p>In stream mode, the framer takes each complete outer frame in a single <code>take</code>, then cuts its messages from the slice it took. Between reads, the front of the buffer is therefore always at a frame boundary, and the framer holds no state from one read to the next. Partial outer frames are never taken.</p><p>The other options each failed a requirement, or were slower:</p><ul><li>PR #983&#39;s design was fragile, and among the slowest of the borrowing designs. The chosen option is 7% to 73% faster on framing alone.</li><li>Deferred advancement meets every requirement with no unsafe code, but it ties a frame&#39;s lifetime to the iterator, so the source can&#39;t record hooks until each frame is done. The chosen option is also 8% to 45% faster on framing alone.</li><li>The two consume-primitive options advance a nested frame piece by piece, so the framer has to remember where it is within an outer frame between reads, and that state becomes invalid if the buffer is cleared or replaced mid-frame. The chosen option is also 1% to 25% faster on framing alone.</li><li>Internal iteration was the fastest, up to 8% ahead on framing alone and level once parsing is included. But the closure can&#39;t <code>.await</code>, so it doesn&#39;t fit the decode loop.</li><li>Reference-counted slices avoid the copy, but cost atomic operations per frame and a pool round trip per buffer. They also stop buffers being collapsed in place, and let a single held frame pin a whole buffer. They were the slowest zero-copy option: the chosen option is 1.5x to 2.9x faster on framing alone.</li></ul><h3 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h3><p>Millions of frames per second, measured in one run with the <code>optimized-release</code> profile, which is how ADP releases are built. Small and medium messages follow the shapes of typical DogStatsD traffic; the SMP shape follows the SMP regression cases.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Today, system allocator</th><th>Chosen, system allocator</th><th>Today, ADP jemalloc</th><th>Chosen, ADP jemalloc</th></tr></thead><tbody><tr><td>Datagrams, small messages</td><td>15.5</td><td>40.5 (2.6x)</td><td>6.3</td><td>41.0 (6.5x)</td></tr><tr><td>Datagrams, SMP shape</td><td>2.9</td><td>5.3 (1.9x)</td><td>2.5</td><td>5.6 (2.3x)</td></tr><tr><td>Stream, one message per frame, small</td><td>7.2</td><td>32.9 (4.6x)</td><td>3.0</td><td>33.3 (11.0x)</td></tr><tr><td>Stream, many messages per frame, small</td><td>20.1</td><td>42.1 (2.1x)</td><td>20.3</td><td>41.5 (2.0x)</td></tr><tr><td>Datagrams, medium, framing and parsing</td><td>2.2</td><td>2.4 (1.1x)</td><td>1.8</td><td>2.4 (1.4x)</td></tr><tr><td>Stream, one message per frame, medium, framing and parsing</td><td>1.8</td><td>2.4 (1.3x)</td><td>1.3</td><td>2.3 (1.8x)</td></tr></tbody></table><p>The chosen option makes no allocations per frame in any layout, and framing drops to about 12% of the combined time to frame and parse a message.</p><p>Beyond the conformance suite, the chosen option was checked with:</p><ul><li>1.35 million random cases of differential fuzzing against today&#39;s framers and an independent model, with no mismatches;</li><li>compile-fail tests for each borrow guarantee;</li><li>mutation tests of the conformance checks themselves.</li></ul><h3 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h3><ul><li>Good, because the DogStatsD source no longer allocates per frame. That&#39;s the biggest gain where it allocated most: streams with one message per frame, and anywhere under ADP&#39;s jemalloc configuration.</li><li>Good, because a frame implies the buffer has been advanced past it, by construction, with no <code>unsafe</code> code.</li><li>Good, because the framer holds no state between reads, so its state can&#39;t fall out of step with the buffer.</li><li>Good, because traffic capture gets each outer frame as a borrowed slice, with no extra copy.</li><li>Bad, because consumers that need an owned frame must now copy it. Before, nested framing could hand them a reference-counted slice of an outer frame it had already copied.</li><li>Bad, because the generic <code>Framer</code> trait and the framers in <code>saluki-io</code> go away. Their only user is the DogStatsD source, so any future protocol needs its own framing.</li><li>Bad, because a caller that stops partway through an outer frame skips that frame&#39;s remaining messages. The decode loop never stops early, so this can&#39;t happen today.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://github.com/DataDog/saluki/pull/983" target="_blank" rel="noreferrer">#983</a>: the previous attempt.</li></ul>',36)])])}const u=t(s,[["render",n]]);export{m as __pageData,u as default};
